const incoming = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const eventType = String(incoming.eventType || 'REPLY_SENT').trim().toUpperCase();
const ticketRef = String(incoming.ticketRef || incoming.ticketReference || incoming.ticketNumber || incoming.ticketId || '').trim();
const rawRecipient = String(incoming.to || incoming.phone || incoming.whatsappNumber || '').trim();
const digits = rawRecipient.replace(/\D/g, '');
const normalizedDigits = digits.length === 10 ? `91${digits}` : digits;
const phone = normalizedDigits ? `+${normalizedDigits}` : '';
const status = String(incoming.ticketStatus || incoming.status || '').trim().toUpperCase();
const defaultMessages = {
  TICKET_RECEIVED: ticketRef ? `Your support ticket ${ticketRef} has been created and is now open.` : 'Your support ticket has been created and is now open.',
  OPEN: ticketRef ? `Your support ticket ${ticketRef} has been reopened. We will continue helping you.` : 'Your support ticket has been reopened. We will continue helping you.',
  IN_PROGRESS: ticketRef ? `Your support ticket ${ticketRef} is now in progress. Our support team is working on it.` : 'Your support ticket is now in progress. Our support team is working on it.',
  CLOSED: ticketRef ? `Your support ticket ${ticketRef} has been closed. If you still need help, reply with this ticket reference.` : 'Your support ticket has been closed. If you still need help, reply to this message.'
};
let message = String(incoming.message || '').trim();
if (!message) message = defaultMessages[status] || defaultMessages[eventType] || (ticketRef ? `Our support team replied regarding ticket ${ticketRef}.` : 'Our support team replied to your support request.');
if (ticketRef && eventType === 'REPLY_SENT' && !message.toLowerCase().includes(ticketRef.toLowerCase())) message = `Ticket ${ticketRef}: ${message}`;
const attachments = Array.isArray(incoming.attachments) ? incoming.attachments.filter(item => item && (item.data || item.base64 || item.content)) : [];
const firstAttachment = attachments[0] || null;
let binary = undefined;
let attachmentType = '';
if (firstAttachment) {
  const mimeType = String(firstAttachment.mimeType || firstAttachment.type || 'application/octet-stream');
  const base64 = String(firstAttachment.data || firstAttachment.base64 || firstAttachment.content || '').replace(/^data:[^;]+;base64,/, '');
  attachmentType = mimeType.startsWith('image/') ? 'image' : 'document';
  binary = { data: { data: base64, mimeType, fileName: String(firstAttachment.fileName || firstAttachment.name || 'support-attachment') } };
}
return [{ json: { eventType, ticketRef, ticketId: incoming.ticketId || ticketRef, ticketStatus: status || 'OPEN', phone, message, hasAttachment: Boolean(binary), attachmentType, mediaCaption: ticketRef ? `Attachment for ticket ${ticketRef}` : 'Support ticket attachment' }, ...(binary ? { binary } : {}) }];
